nx = 100
ny = 25
nz = 2
wcs_header = {
    'WCSAXES': 3,
    'CRPIX1': (nx + 1)/2,
    'CRPIX2': (ny + 1)/2,
    'CRPIX3': 1.0,
    'PC1_1': 0.0,
    'PC1_2': -1.0,
    'PC1_3': 0.0,
